template.css:
.analog-gauge {
  display: inline-block;
}
.gauge-bg {
  fill: #1a1a2e;
  stroke: #00ff88;
  stroke-width: 2;
}
.gauge-arc {
  fill: none;
  stroke-width: 20;
}
.low-zone { stroke: #ffaa00; }
.normal-zone { stroke: #00ff88; }
.high-zone { stroke: #ff0044; }
.gauge-needle {
  fill: #00ccff;
  transform-origin: 100px 100px;
  transition: transform 0.3s ease;
}
.gauge-center {
  fill: #00ff88;
}
.gauge-value {
  fill: #00ccff;
  font-size: 24px;
  font-weight: bold;
  text-anchor: middle;
}
.gauge-units {
  fill: #888;
  font-size: 14px;
  text-anchor: middle;
}
.gauge-title {
  fill: #00ff88;
  font-size: 16px;
  font-weight: bold;
  text-anchor: middle;
}

template.js:
function initAnalogGauge(element, config) {
  const svg = element.querySelector('svg');
  const needle = svg.querySelector('.gauge-needle');
  const valueText = svg.querySelector('.gauge-value');

  function updateGauge(value) {
    const percent = (value - config.min) / (config.max - config.min);
    const angle = -135 + (percent * 270);
    needle.style.transform = `rotate(${angle}deg)`;
    valueText.textContent = value.toFixed(config.decimals || 1);

    // Update color based on alarm zones
    if (value < config.alarmLow || value > config.alarmHigh) {
      needle.style.fill = '#ff0044';
    } else if (value < config.warnLow || value > config.warnHigh) {
      needle.style.fill = '#ffaa00';
    } else {
      needle.style.fill = '#00ccff';
    }
  }

  return { updateGauge };
}
